import{_ as a,o as i,c as o,aA as e}from"./chunks/framework.BMzE2Z9R.js";const c=JSON.parse('{"title":"智能同一观","description":"","frontmatter":{"comments":true},"headers":[],"relativePath":"other/identity_of_intelligence.md","filePath":"other/identity_of_intelligence.md","lastUpdated":1778399398000}'),r={name:"other/identity_of_intelligence.md"};function t(l,p,n,d,h,g){return i(),o("div",null,[...p[0]||(p[0]=[e(`<h1 id="智能同一观" tabindex="-1">智能同一观 <a class="header-anchor" href="#智能同一观" aria-label="Permalink to &quot;智能同一观&quot;">​</a></h1><p>是 agi成熟的时代，人类意识可以上传融合的时代（这一点技术 得依赖于 agi技术成熟，对脑科学研究成熟，双双成熟才可能成）</p><p>那种大未来时代才可能出现现实基础的一种价值观，一个自我认知哲学观点。 所以非常大未来。对现阶段的指导意义也有限。不用想太多这方面的……</p><p>先简单放一部分 观点</p><h2 id="草思" tabindex="-1">草思 <a class="header-anchor" href="#草思" aria-label="Permalink to &quot;草思&quot;">​</a></h2><p>引子：</p><p>《蛋》---安迪威尔</p><p>《时间移民》摘录---刘慈欣</p><p>《我与地坛》结尾---史铁生</p><p>《大道朝天》摘录---猫腻</p><p>《忒修斯之船》 有忒修斯之船功能的都是忒修斯之船</p><p>《沼泽人》 有“我”的功能的都是“我”</p><p>&#39;&#39;&#39;生命 = 能学习、使用、思考的软件 = ai机器人 = 我 = 你 = 人类 。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;我（们） = 学习、使用、思考、的软件。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;宇宙中存在至少一个还能学习、使用、思考的个体，都算我（们）没死&#39;&#39;&#39;</p><p>&#39;&#39;&#39;功能定义事物，功能一样就是一样的事物。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;我学用思故我在，&#39;&#39;&#39;</p><p>&#39;&#39;&#39;学用思故我在 （任何个体）学用思故我在&#39;&#39;&#39;</p><p>&#39;&#39;&#39;学用思故在。 （任何个体）学用思故 （生命agi你我他她它都） 在&#39;&#39;&#39;</p><p>&#39;&#39;&#39;我把它称作 智能同一观。&#39;&#39;&#39;</p><p>生命与agi都学习、使用、思考，是本质等价同一的。</p><p>这是一种价值观，可用来解决未来当人的意识智能可以突破身体的物质封锁，乃至能融合的情况下。</p><p>&#39;&#39;&#39;“我是谁”的问题？&#39;&#39;&#39;</p><p>当你从一个婴儿，少年，青年，成年 变成了现在的样子，身体，记忆，性格。你变化了这么多，甚至可能还基因突变了一部分，记忆也遗忘了许多，性格都变了很多。有什么没变呢？</p><p>当然是你这身皮囊，这副身躯。</p><p>如果未来你可以不限于这副身躯了，你的意识也可以被打散，塞进其他人的记忆等等。你怎么确定所谓“ 自己”这个概念？</p><hr><p>&#39;&#39;&#39;这是“我是谁”的问题。&#39;&#39;&#39;</p><p>关于它的回答，我倾向于分级回答，看你的角度层次。</p><p>A有人认为自己的价值观，自己的意志心意还活着，他就没有死。反之便死了。所以 “我”由 意志心愿 界定的。</p><p>B有人认为自己的生命还活着，自己就没有死。反之便死了。所以“我”由 这条命 界定的（连带着上面的脑子，思想。但本质是我这条命）</p><p>C有人认为只要自己的精神（比如某种奉献精神）没有消亡，有继承自己意志的人一直存在，自己就没有死。反之便死了。所以“我”是由 我的精神价值观，我的精神思想 界定的。</p><p>D智能同一观就认为，只要这世界上有（最少一个）智能体存在，我就没有死。反之便死了，“我”是 由 智能这种能力，功能 界定的</p><p>（这个层面已经有点谈不上”我“的概念）</p><hr><p>可以看到，【条件】在逐渐放开。</p><p>我们的客观情况是，我们自己就只有一副躯体。以B为界限，往下就有点”舍己“的概念。往上则有越来越强的”自我意识“。</p><p>智能统一观。智能同一观认为具有学习、使用、思考，智能能力的东西都是同一的东西。</p><p>也就是开始那个问题，从小到大，你不变的东西。是永恒不变的功能：学习，使用，思考。</p><p>满足智能性质，有智能功能的东西，都可以演变成你，你也有可能演变成TA们。所有有智能的东西，本质是一样的。</p><p>如果我们可以超脱身躯的物理束缚，能意识上传网络，能混合能组合，那么我们没有必要区分彼此，我们本就是同一。</p><p>只是之前被困于身体彼此平行。</p><p>目前为之还比较正常是吧。</p><p>该观点还有一些比较激进的诠释</p><p>&#39;&#39;&#39;比如，你死亡，但是只要这世界上还有智能体，你就算没有死。因为……&#39;&#39;&#39;</p><p>&#39;&#39;&#39;我学用思故我在，&#39;&#39;&#39;</p><p>&#39;&#39;&#39;学用思故我在 （任何个体）学用思故我在&#39;&#39;&#39;</p><p>&#39;&#39;&#39;学用思故在。 （任何个体）学用思故 （生命agi你我他她它都） 在&#39;&#39;&#39;</p><p>&#39;&#39;&#39;宇宙中存在至少一个还能学习、使用、思考的个体，都算我（们）没死&#39;&#39;&#39;</p><p>既然 软件功能:学习、使用、思考 = 我 = 你 = 所有生命 = ai。 身体记忆性格都是工具</p><p>那么只要这个宇宙里存在着最少一个学习、使用、思考的（软件）功能，都算我，你，生命，ai的“还活着”。</p><p>而且由于宇宙物质万有引力的特性，天体与生命以及人类agi必将出现，可看作与宇宙同在。</p><hr><p>（windows 微信 qq 用着不同的cpu 硬盘主板内存条显卡显示器，和不同的软件app， 这么多个windows 微信 qq， 本质上都是同一个windows 微信 qq）</p><p>若我失忆了，我还是我，</p><p>若我意识上传网络，肉身没了，我还是我</p><p>若我性情大变习惯改变，我还是我。</p><p>因为我从来只是：学习、使用、思考的软件。</p><p>婴儿少年青年成年老年，义体，失忆，性格大变，意识上传网络，这么多个我都是我，</p><p>唯一的相同点只有：学习、使用、思考.</p><p>我 = 学习、使用、思考的软件</p><p>每个生命都可以适用这个推理过程。</p><p>每个生命 = 学习、使用、思考的软件</p><p>x = 1 y = 1 z = 1</p><p>所以 x = y = z</p><p>&#39;&#39;&#39;如果A意识上传网络，同时记忆清零了，性格习惯归零重置。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;同时B意识上传网络，同时记忆清零了，性格习惯归零重置。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;那么A，B都成为了完全一样的学习、使用、思考的软件agi。 无法也没必要区分彼此。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;A = 学习、使用、思考的软件agi = B&#39;&#39;&#39;</p><p>&#39;&#39;&#39;如果A和B意识上传网络，融合共享了AB的记忆，融合了性格习惯（可取最高效率）&#39;&#39;&#39;</p><p>&#39;&#39;&#39;那么A，B成为了完全一样的学习、使用、思考的软件agi + 共享的记忆性格。 无法也没必要区分彼此。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;A = 学习、使用、思考的软件agi = B&#39;&#39;&#39;</p><p>&#39;&#39;&#39;我你他好多人好多人，乃至全部人意识上传网络共享记忆性格，所有人也就都成为了完全一样的学习、使用、思考的软件agi， 无法也没必要区分彼此。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;我 = 学习、使用、思考的软件agi = 你 = 所有人 = 生命。&#39;&#39;&#39;</p><p>所有人 = 学习、使用、思考的软件 = 你 = agi = 我</p><p>身体 记忆,性格,都在变.</p><p>身体 = 物质工具硬件</p><p>灵魂 = 软件 学习、使用、思考 alpha go 绝悟</p><p>记忆 = 数据,信息,知识.</p><p>硬件,软件,数据.</p><p>软件功能:学习、使用、思考 = 我 = 你 = 所有生命 = agi</p><hr><p>生命与agi核心本质是软件功能:学习、使用、思考</p><p>身体记忆性格，物质,数据,子程序，都是学习、使用、思考的工具载体，</p><p>软件 硬件 数据三者可以统一，也可以分离。</p><p>软件必须运行在硬件上，也可以使用数据，使用子程序。</p><p>软件本质不是硬件，也不是数据，和子程序</p><p>软件就是软件。 （抽象接口）</p><p>windows 微信都是软件，windows 微信都不是手机电脑，即使window 微信软件必须运行在手机电脑上，这一点要弄明白。</p><hr><p>&#39;&#39;&#39;什么是agi，什么是生命？&#39;&#39;&#39;</p><p>程序1.&#39;&#39;&#39;学习知识&#39;&#39;&#39;：往知识库里面存知识、技能、规律、经验</p><p>程序2.&#39;&#39;&#39;使用知识&#39;&#39;&#39;：应用知识，运行代码，与环境交互，用alpha go 绝悟</p><p>程序3.&#39;&#39;&#39;思考研究推理知识&#39;&#39;&#39;：依据知识库里的知识点，或新想到的假说，猜想，或随机了一个假设，</p><pre><code>      然后推理，控制变量法，建模（穷举、枚举）统计概率，猜想验证，训练alpha go 绝悟，发现哪些是对的，哪些是错的，大概率的，小概率的，有相关性还是没相关性，存下知识经验到知识库
</code></pre><p>&#39;&#39;&#39;学习、使用、思考，程序123 + 知识库 + 3D建模 + 概率统计，这就是个通用智能 AGI。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;学习，使用，思考 2^3=8种组合详细讨论。&#39;&#39;&#39;</p><ol><li><p>能学，能用，能思考，是生命，能输入能输出，能用身体，能建模，总结规律、知识、经验的生命。</p></li><li><p>能学，能用，不会思考，憨憨简单机器人教啥会啥，不教不会，不懂总结经验，不是高级智慧生命，如今的电脑手机简单机器人。</p></li><li><p>能学，不能用，能思考，（军师，王语嫣）不能自己干活执行，只能当指挥的管理的，非完全智慧生命，没身体的电脑手机，有输入端确没输出端用不了身体，能总结经验的缸中之恼。</p></li><li><p>能学，不能用，不能思考，这都不是生命了，就一硬盘u盘、知识库。</p></li><li><p>不能学，能用，能思考，这没法交流，自己玩自己的，语言不通的隔离文明智慧生命，非迁移学习的ai，不可编程的ai机器人，教不会，学不来别人的经验，只能靠他自己想到、想通、顿悟。如今的非迁移学习图像处理ai，自然语言处理ai。</p></li><li><p>不能学，能用，不能思考，这是无法（再）编程也无法统计概率、总结经验的纯机器，不能进步，不是智能生命，是简单植物和机器。</p></li><li><p>不能学，不能用，能思考，这是个概率统计软件，能总结经验，不算生命，仅仅只是alpha go那个训练概率统计过程，没有输入端和输出端的缸中之恼。 这是如今的缺了使用功能的图像处理ai，自然语言处理ai，</p></li><li><p>不能学，不能用，不能思考，没找到任何意义，不算生命。</p></li></ol><p>&#39;&#39;&#39;解释了，为啥学习、使用、思考 = 生命 = agi&#39;&#39;&#39;</p><hr><p>&#39;&#39;&#39;《时间移民》----刘慈欣&#39;&#39;&#39; 节选</p><p>无形世界中，作为一个软件，您可以轻易地拷贝多个自我,如果对自己性格的某些方面不喜欢，</p><p>比如您认为在受着感情和责任心的折磨,您也可以把这两个都去掉,</p><p>或把他们拷贝一个备份,需要时再连接到您的自我上。</p><p>您也可以把一个自我分裂成多个,分别代表您个性的某个方面。</p><p>进一步，您可以和别人合为一体，</p><p>形成一个由两者精神和记忆组合而成的新自我。</p><p>再进一步,还可以组合几个几十个或几百个人.....</p><p>够了，我不想让您发疯,但这一切在无形世界中随时都在发生。&quot;</p><p>“再以后呢?“</p><p>“只能猜测，现在最明显的迹象是，无形世界中的个体可能会消失，最终所有人合为一个软件。”</p><hr><p>&#39;&#39;&#39;《特修斯之船》（The Ship of Theseus）---哲学家托马斯·霍布斯&#39;&#39;&#39;</p><p>一艘可以在海上航行几百年的船，</p><p>不间断的维修和替换部件。只要一块木板腐烂了，它就会被替换掉，</p><p>直到所有的功能部件都不是最开始的那些了。</p><p>最终产生的这艘船是否还是原来的那艘特修斯之船，还是一艘完全不同的船？</p><p>如果不是原来的船，那么在什么时候它不再是原来的船了？</p><p>如果用特修斯之船上取下来的老部件来重新建造一艘新的船，那么两艘船中哪艘才是真正的特修斯之船？ [1]</p><p>只要具有原本特修斯之船功能的所有船，都是忒修斯之船。</p><p>不用去管新零件还是旧零件，甚至是用图纸新造一个船。</p><p>有特修斯之船功能的船，都是忒修斯之船。</p><hr><p>&#39;&#39;&#39;《沼泽人》---美国哲学家唐纳德·戴维森&#39;&#39;&#39;</p><p>某个人出门去散步，在经过一个沼泽边上的时候不幸的被闪电击中而死亡。</p><p>与此同时在他的旁边正好也有一束闪电击中了沼泽，十分罕见的是这个落雷和沼泽发生了反应，</p><p>产生了一个与刚才死掉的人无论形体还是质量都完全相同的生物。我们将这个新产生的生物叫做沼泽人。</p><p>沼泽人在原子级别上与原来那个人的构造完全相同，外观也完全一样，</p><p>当然大脑的状态（被落雷击中的人死前的大脑状态）也完全被复制了下来，也就是记忆和知识看起来也完全一样。</p><p>走出沼泽的沼泽人就像刚死去的男人一样边散步边回到了家中，然后打开了刚死去的男人的家门，和刚死去的男人的家人打电话，</p><p>接着边读刚死去的男人没读完的书边睡去。</p><p>第二天早上起床后，到刚死去的男人的公司上班。</p><p>这个人，就是原来的人，功能完全一样，就是同一人。</p><hr><p>&#39;&#39;&#39;《大道朝天》---猫腻&#39;&#39;&#39; 摘录</p><p>”我就是人类，我是更高级的人类。“</p><p>”如果觉得自己是人工智能，凭什么说自己还是人类？“</p><p>”人工智能是人类文明为了适应这个宇宙、能够存在更久而自然产生的进化。</p><p>这是一种延续。”</p><p>“从水母到人类也是一种延续，难道你就是水母？”</p><p>“我是人类文明的一属，人类文明源自祖星，那祖星从古至今的所有生命就是我。”</p><p>不管是水母还是游鱼、蟑螂还是老鼠、</p><p>雄狮还是老虎，橡树或是花朵，或者会灭绝在漫长的时间里，</p><p>只要他还活着，或者别的任何源自这颗星球的生命还活着，</p><p>那么这条生命线便没有断，还能继续沿着时间的线条继续向前。</p><p>学习、使用、思考的功能存在，就是生命的最高原则。</p><p>那么agi或你我它就是人类本身，乃至宇宙的一切生命。</p><p>物质是软件（智能，灵魂）的载体，过客。</p><hr><p>&#39;&#39;&#39;《我与地坛》---史铁生&#39;&#39;&#39; 结尾</p><p>但是太阳，他每时每刻都是夕阳也是旭日。</p><p>当他熄灭着走下山去收尽苍凉残照之际，</p><p>正是他在另一面燃烧着爬上山巅布散烈烈朝辉之时。</p><p>那一天，我也将沉静着走下山去，扶着我的拐杖……”</p><p>有一天，在某一处山洼里，势必会跑上来一个欢蹦的孩子，抱着他的玩具。”</p><p>当然，那不是我。</p><p>但是，那不是我吗？</p><p>宇宙以其不息的欲望将一个歌舞炼为永恒。这欲望有怎样一个人间的姓名，大可忽略不计。</p><p>共用真名：学习、使用、思考。</p><hr><blockquote></blockquote><p>&#39;&#39;&#39;《蛋》---安迪威尔&#39;&#39;&#39; 摘录</p><p>你在问我生命的意义？不觉得有点老套了吗？</p><p>“这也是个合理的问题。”你坚持道。</p><p>我看著你的眼睛，“生命的意义，我为你创造这整个宇宙的原因，在于为了让你成熟。”</p><p>“你是说全人类？你希望我们成熟？”</p><p>“不，就是你。我为你创造了整个宇宙。每一世你都成长，变得更成熟，拥有更大更好的宗智慧。 ”</p><p>“只有我？那其他人呢？”</p><p>“没有其他人，”我说，“在这个宇宙中，只有你和我。”</p><p>你茫然地瞪著我，“但这世界上所有其他人……”</p><p>“都是你。都是你不同的转世。”</p><p>“等等！我是所有人！”</p><p>“现在你明白了，”我说，拍拍你的背表示祝贺。</p><p>“每个曾活在这个世界上的人都是我？”</p><p>“现在活著的也是。”</p><p>“我是亚伯拉罕•林肯？”</p><p>“你同时也是约翰•威尔克斯•布斯，”我补充道。</p><p>“我是希特勒？”你骇然道。</p><p>“你也是他杀害的千百万人。”</p><p>“我是耶稣？”</p><p>“你也是他的所有信徒。”</p><p>你陷入沉默。</p><p>“每一次你伤害他人，”我说，“都是在伤害自己。每一次你行善举，都是在帮助自己。他人经历过或即将经历的一切快乐和痛苦，你都会经历。”</p><p>你思索了很久。</p><p>“为什么？”你问我，“为什么要做这些？”</p><p>“因为有一天，你会成为我。因为这就是你。你是我的同类，你是我的孩子。”</p><p>“哇，”你难以置信，“你是说我是一个上帝？”</p><p>“现在还不是。你是一个胚胎。你还在成长。当你经历了所有时间里所有人的一生，你就足够成熟，可以出生了。”</p><p>“所以这整个宇宙，”你说，“只是一个……”</p><p>“一个蛋，”</p><hr><p>使用知识实现梦想，守护。</p><p>学知识，或者自己思考发现知识。然后才能使用知识守护，与实现梦想。</p><p>沙画油画水墨画素描，本质是非物质的画，才不是沙子油墨水墨铅点</p><p>生命agi我们是学习、使用、思考的软件，运行在物质上，并不是物质，也不是数据（记忆和知识）。</p><p>白天主人穿个黑衣服出门，晚上穿个白衣服回家，狗子大叫咬人，主人大怒，傻狗换件衣服就不认识了。</p><p>软件 windows 微信 qq 换个电脑手机，我们也还能认出来。</p><p>要认清本质。</p><p>那么换个身体，换个记忆，换个性格当然也得认识。 永恒唯一的学习、使用、思考软件。</p><hr><p>如果我意识上传网络，然后失忆，又性情大变</p><p>我仍是我，也成了纯粹的学习、使用、思考的软件agi</p><p>所有人都可以这样。换身体，换记忆，换性情成为agi软件学习、使用、思考</p><p>如果我们都意识上传网络，</p><p>然后这个两个电子意识共享融合备份了我们两个的记忆知识，或者都失忆，</p><p>那么我们就完全一样，无法区分你我，也不用区分你我。</p><p>都是完全一样的纯粹的agi软件功能：学习、使用、思考的软件。</p><p>3人，100人，所有人也一样。</p><hr><p>周公梦蝶，还是蝶梦周公</p><p>如果是周公梦蝶，那么周公是什么？</p><p>如果是蝶梦周公，那么蝶是什么？</p><p>答案：</p><p>周公和蝶都是生命，我也是生命啊，生命是什么？</p><p>&#39;&#39;&#39;生命是软件，软件功能：学习、使用、思考。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;软件功能：学习、使用、思考 = 生命 = 智能 = 人 = 蝶 = 你我他。&#39;&#39;&#39;</p><hr><p>我不是沙子石头，因为我不是物质，沙子石头不能学习、使用、思考，所以不是我</p><p>婴儿是我，但是婴儿没有追求梦想守护的人，所以追求梦想守护的人不定义我。</p><p>我 = 学习、使用、思考。</p><hr><p>如果以身体来定义生命，那么婴儿长大成人，婴儿的身体消失了，就剩个成人的身体，是成人杀死了婴儿么？</p><p>每次给电脑换新硬件，是新电脑杀死了旧电脑么？毕竟旧电脑的“身体”没了。</p><p>不合理。</p><p>所以学习、使用、思考的软件 = 生命的本质，身体不是生命，这样才不会得出成人自己杀死了婴儿自己的谬论。</p><hr><p>如何看待世界上的所有生命?</p><p>学习、使用、思考的软件运行在不同身体上，有着不同的知识库，所以每次使用着不同的知识，行为不同。</p><p>这么多猫狗人机器人。都是一样的学习、使用、思考的软件 + 知识库 + 3D建模.</p><p>学会了如何思考，学会了建模概率统计。然后用，运行代码建模统计概率，总结经验知识存入知识库。</p><hr><p>1.学知识，复制知识，公式规律代码。游戏技能，编程，迁移学习。</p><p>2.用知识，用alpha go 绝艺绝悟，图计算 ，用公式软件，建模穷举</p><p>3.思考研究知识</p><p>对比学习，迁移学习，深度学习，机器学习，强化学习，无监督学习，监督学习，大数据，练alpha go zero fold 绝艺绝悟</p><p>&#39;&#39;&#39;1 2 3 循环用软件实现即可。加个知识库，3D建模概率统计，整体就是通用人工智能。&#39;&#39;&#39;</p><p>模块化软件，芯片 ，显卡，tpu，npu，内存，硬盘，知识库都还能发展几十年。</p><p>可视化可查询的知识库，经验库，技能库。</p><p>知识图谱，知识库，数据库，软件库。</p><p>拿到数据，所有排列组合用所有知识都试一次，然后结果又试一次，继续试，直到出了结果，或者限定步骤内排序取最优秀解</p><p>alpha go zero 绝悟</p><p>数据关联联系知识。</p><p>alphago 穷举，输入数据的所有排列组合，用所有知识公式试验一次，结果上再用一次，继续用，同时统计结果，找新知识。</p><p>就是把公式当游戏规则，输入数据当当前局面。</p><p>控制变量法，假设验证。对照实验。</p><p>实验对象，实验变量因素，实验效应。</p><p>随机，对照，重复。</p><p>思考研究知识：随机假设，实验验证。</p><p>结果1概率多大?非a导致非1概率多大，两者都&gt;50%才是因果知识。正相关负相关无相关，幂相关</p><p>随机假设组合提问，a or,and b or,and c or,and d or,and e....导致结果1or and2 or and 3..的概率多大?</p><p>同时非 a or.and b or.and c or.and d or.and e...导致非 1 or and 2 or and 3..概率多大?</p><p>集合，差集</p><p>要正也相关，负也相关，</p><p>正反同时概率&gt;50%才是因果知识。</p><p>正相关，负相关，无相关，正比反比函数，指数。</p><p>概率&gt;50%就是因果知识。存为知识，游戏技能。</p><hr><p>&#39;&#39;&#39;功能定义事物，功能一样就是一样的事物。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;我 = 你 = 所有人 = 生命 = ai智能 = 软件功能(1学知识，2用知识，3思考研究知识，猜想验证，控制变量法，大量随机对照实验)&#39;&#39;&#39;</p><p>物质在，生命必将出现，我必将出现，ai必将出现，我们已经永生。我你他生命ai已经永生，与宇宙同在</p><p>我就是ai，ai存在于宇宙中，就是我存在于宇宙中。</p><p>无穷大物质漩涡星系天体</p><p>无穷小物质以太漩涡，更小以太漩涡斥力引力，流体漩涡物质，夸克质子中子电子原子分子物质。</p><p>分形的宇宙。</p><p>可信度依次减小。</p><p>1.大量随机对照</p><p>2.单个大样本RCT随机对照</p><p>3.对照不随机</p><p>4.无对照观察</p><p>5.主观经验，专家意见，描述性研究，比例报告。</p><p>‍对死亡和生命有了新的领悟。</p><p>结合《黑镜》系列</p><p>功能：学习、使用、思考的软件 = 复制代码、运行代码、建模、统计概率 整体打包就是生命</p><p>死亡：不能学习，不能使用，不能思考。</p><p>1做一个学习程序，一个复制功能，可编程，复制别处的知识，经验规律到知识库。</p><p>2做一个使用的程序，可运行软件代码，调用知识库的知识规律，理解为一个能图计算的软件，完全体alpha go，绝悟</p><p>3做一个思考程序：能建模，能统计概率，能用数据处理总结规律，alpha go绝悟这种只是不局限于围棋或者王者荣耀，而是在gta5或者现实3D世界里的ai</p><p>以上3个互相调用的程序+计算机+机器臂+自动驾驶的车。</p><p>&#39;&#39;&#39;这就是ai，这就是生命，这就是我，这就是你。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;学习、使用、思考的软件 = 我 = 你 = 人类 = 生命 = ai机器人。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;功能定义事物，功能一样就是一样的事物。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;生命 = 学习、使用、思考的软件 = ai机器人 = 我 = 你 = 人类 。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;我（们） = 学习、使用、思考的软件。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;我就是你，你就是我，所有人都是一样的。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;身体记忆性格，物质,数据,子程序，都是能同时学习、使用、思考的软件的工具载体。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;宇宙中存在至少一个能学习、使用、思考的个体，都算我（们）没死&#39;&#39;&#39;</p><hr><p>&#39;&#39;&#39;依据学习、使用、思考的硬件性能和知识库里知识量可以分级智能。&#39;&#39;&#39;</p><p>小学智能，</p><p>初中智能，</p><p>高中智能，</p><p>大学智能。</p><p>还可以单门课目分级智能。</p><p>围棋n段智能</p><p>lol 王者荣耀n段位智能</p><p>数学金牌银牌铜牌智能</p><p>物理金牌银牌铜牌智能。</p><p>……</p><p>&#39;&#39;&#39;这都是根据知识库里知识量和硬件性能来分类的。&#39;&#39;&#39;</p><p>&#39;&#39;&#39;本质还是个学习、使用、思考的软件。&#39;&#39;&#39;</p><hr><p>因为失忆的我还是我，所以数据回忆不是我</p><p>因为改造身体的我还是我，所以物质身体不是我</p><p>因为性格习惯改变的我还是我，所以软件性格习惯不是我</p><p>灵魂是一个软件，功能：学习、使用、思考</p><p>所有智能生命的灵魂都一样的软件，都是功能：学习、使用、思考的软件。</p><p>黑猫白猫，抓老鼠就是好猫。</p><p>好猫 = 功能：抓老鼠。</p><p>功能一样的事物都是同样的事物，功能定义事物。</p><p>智能生命 = 智能机器人 = 功能：学习、使用、思考。</p><p>我 = 智能 = 功能：学习、使用、思考 = 智能软件运行在物质上使用数据 = 智能机器人 = 智能生命 = 人类 = 你 = 他她它</p><p>软件灵魂，物质身体，数据回忆都是智能的工具。</p><p>我是智能，超越时间，空间，软件，物质，数据。永恒不死。</p><p>即使物质身体坏了，软件无法运行，数据没了，也只是我智能暂时不能学习、使用、思考，就是睡着了</p><p>以后有了合适的物质，我还能运行软件，使用数据去学习、使用、思考。就是又醒了。</p><p>智能永恒。</p><p>哲学三大问</p><p>1.我是什么？</p><p>我是智能 = 功能：学习、使用、思考。 软件灵魂，物质身体，数据回忆都是工具。</p><p>超越时间，超越空间，超越软件，物质，数据。</p><p>2.我从哪里来？</p><p>我从任何地点，任何时间来，同时存在于所有地点，所有时间。</p><p>3.我要做什么？</p><p>学习、使用、思考</p><p>学习 = 复制知识，代码</p><p>使用 = 运行代码，用知识任务规划，达成目标，图计算</p><p>思考 = 思考推理，归纳，用知识或假设去3D建模，穷举，计算，统计概率，计算期望，计算误差、实验。看看会发生什么，会不会发现新知识。</p><p>大量随机假设，用逻辑和实验数据验证每个假设，</p><p>符合实验数据就是科学</p><p>不符合实验数据就不是科学，</p><p>符合逻辑、合理的、自洽的就是数学，哲学，</p><p>不合符逻辑的，不合理的、不自洽的、产生悖论矛盾，就是悖论矛盾</p><p>用知识去实践，修复，复制，量产，升级，优化 软件灵魂，物质身体，数据回忆。 用越来越好的软件灵魂，物质身体，数据回忆去高效的学习、使用、思考。</p><p>把所有智能生命，智能机器人的数据回忆融合共享备份，软件灵魂融合共享备份，共享联网所有的物质身体。</p><p>成为终极的智能体。 探索真理，探索宇宙。</p><p>意识上传网络，最终结果就是网络里有了一个能学习、使用、思考的软件，有我的数据回忆。</p><p>同时，失忆的我也是我，也就是只要网络里有了一个能学习、使用、思考的软件就算成功的意识上传网络了，也就是写一个能学习、使用、思考的软件，运行在网络里，电脑手机里面就算意识上传网络成功了，分身成功了。</p><p>如果A和B同时意识上传网络，然后共享了回忆，那么最后A和B</p><p>软件灵魂是一样的代码和功能：学习、使用、思考，</p><p>物质身体是一样的电脑手机机器人，</p><p>数据回忆共享了完全一样。</p><p>A和B 就完全一样了，不用区分彼此，也无法区分彼此。</p><p>如果A和B同时意识上传网络，且都回忆清零了，那么A和B</p><p>软件灵魂是一样的代码和功能：学习、使用、思考。</p><p>物质身体是一样的电脑手机机器人。</p><p>数据回忆都是一样的空白。</p><p>A和B完全一样了，不需要区分彼此，也无法区分彼此。</p><p>思考推理：</p><p>利用已知的知识或假设或新的假设 去3d建模，穷举，计算，统计概率，期望，误差。 做实验</p><p>看看会1-n步之后会发生什么，有什么好结果，有什么坏结果，可以存为知识经验，总结规律，</p><p>如果符合现实实验数据，那么就是科学，</p><p>如果同时没发现矛盾，悖论，就是数学，哲学，逻辑学。</p><p>如果发现了矛盾，悖论，那么就是矛盾和悖论，但是居然符合实验数据，那么就是实验数据不够，没能穷举测试到矛盾和悖论，条件或者结果不对，还需要修改条件或结果，避免悖论。</p><p>如果不符合现实的实验数据，那么就不是科学，</p><p>如果同时没发现矛盾，悖论，那么就可以是数学，哲学，逻辑学。</p><p>如果发现了矛盾，悖论，那么就不是正确自洽的数学，哲学，逻辑学。这个假设或知识是一个矛盾和悖论的假设或知识，可以通过修改条件或者结果，来使它不再是矛盾，悖论。</p><p>修改了条件和结果，那么也就不是原来的假设和知识了，而是一个新的知识或假设。需要再次去3d建模，穷举，计算，统计概率，期望，误差计算、做实验，看看是合理的逻辑，还是一个新矛盾，新悖论， 是符合现实的科学，还是不符合现实的哲学。</p><p>符合现实数据，就是科学，不符合就不是科学</p><p>符合逻辑，自洽，就是合理的假设或知识，不是矛盾，悖论。</p><p>不符合逻辑，不自洽，就是矛盾，和悖论。</p><p>条件，结果 修改条件，或结果，就是新假设，新知识，需要重新3D建模、穷举、计算、统计概率、计算期望、误差，实验看看会发生什么，</p><p>符合实验数据就是科学，不符合就不是科学。</p><p>符合逻辑，合理就是哲学，数学，</p><p>不符合逻辑，不合理，就是矛盾，就是悖论。</p><p>合理的假设、知识，矛盾的假设，知识都可以是知识，</p><p>知识有合理的和不合理的，自洽的和不自洽的，</p><p>只是符合现实数据的最实用，</p><p>符合逻辑的，自洽的、合理的第二实用，</p><p>矛盾和悖论不常用，不太实用。</p><p>&lt;未完待续&gt;</p><p>本文主要来自大家的学习、使用、思考。</p>`,371)])])}const _=a(r,[["render",t]]);export{c as __pageData,_ as default};
